      { method: 'GET', path: '/webhook/dashboard-html',              desc: 'Dashboard estudio (proyectos, finance, concierge)' },
      { method: 'GET', path: '/webhook/security-dashboard-html',    desc: 'Eventos seguridad + blocklist + top IPs' },
      { method: 'GET', path: '/webhook/llm-costs-html',              desc: 'Costes LLM por agente, proyecto, modelo' },
      { method: 'GET', path: '/webhook/admin-llm-stats',             desc: 'Stats LLM 24h/7d/30d + banner unknown_agent' },
      { method: 'GET', path: '/webhook/admin-pipeline-metrics',     desc: 'Distribucion por fase + estancados >14d' },
      { method: 'GET', path: '/webhook/admin-pipeline',              desc: 'Kanban visual de proyectos' },
      { method: 'GET', path: '/webhook/admin-trades-summary',       desc: 'Ratios por gremio + top 15 suppliers' },
      { method: 'GET', path: '/webhook/admin-compliance-overview',  desc: 'Grade A/B/C/D + 11 checks por proyecto (sin LLM)' },
      { method: 'GET', path: '/webhook/admin-tokens',                desc: 'Vista read-only de client_access_tokens' },
      { method: 'GET', path: '/webhook/admin-search?q=<term>',       desc: 'Busqueda transversal' },
      { method: 'GET', path: '/webhook/admin-activity',              desc: 'Timeline 48h security events + activity_log' },
      { method: 'GET', path: '/webhook/admin-health-history',        desc: 'Tendencia 30d health score (SVG)' },
      { method: 'GET', path: '/webhook/admin-workflows',             desc: 'Status crons criticos (OK/STALE/NEVER)' },
      { method: 'GET', path: '/webhook/admin-help',                  desc: 'Pagina de ayuda con FAQ' },
      { method: 'GET', path: '/webhook/admin-endpoints',             desc: 'ESTA pagina (lista de endpoints)' },
      { method: 'GET', path: '/webhook/admin-export?dataset=<name>', desc: 'Export CSV multi-dataset' },
      { method: 'GET', path: '/webhook/admin-project?project_id=<uuid>', desc: 'Drill-down por proyecto' },
      { method: 'GET', path: '/webhook/admin-notes-list?project_id=<uuid>', desc: 'Listado de notas (filtrable)' }
    ]
  },
  {
    title: 'JSON endpoints',
    color: '#10b981',
    items: [
      { method: 'GET',  path: '/webhook/dashboard-summary',         desc: 'Mismo que dashboard-html pero JSON' },
      { method: 'GET',  path: '/webhook/security-dashboard',        desc: 'Security dashboard JSON' },
      { method: 'POST', path: '/webhook/audit-project',             desc: 'Run compliance audit por proyecto', body: '{"project_id":"<uuid>","send_email":true}' }
    ]
  },
  {
    title: 'Agentes (POST con auth)',
    color: '#8b5cf6',
    items: [
      { method: 'POST', path: '/webhook/new-project',                  desc: 'Inicia proyecto nuevo (init_new_project)', body: '{"client_email":"...","client_name":"...","project_name":"...","project_type":"reforma_integral","property_type":"piso","property_area_m2":72,"location_city":"Madrid","location_province":"Madrid","budget_target":48000,"architect_intake_notes":"..."}' },
      { method: 'POST', path: '/webhook/contract-generate',            desc: 'Generar contrato con plantilla', body: '{"project_id":"...","contract_type":"encargo_profesional","parties":[],"scope":"..."}' },
      { method: 'POST', path: '/webhook/contract-signed',              desc: 'Marcar contrato firmado', body: '{"contract_id":"..."}' },
      { method: 'POST', path: '/webhook/certificate-generate',         desc: 'Generar certificado', body: '{"project_id":"...","certificate_type":"cfo","signer_name":"...","collegiate_no":"..."}' },
      { method: 'POST', path: '/webhook/permit-register',              desc: 'Registrar nuevo permit' },
      { method: 'POST', path: '/webhook/site-report',                  desc: 'Vision LLM analiza foto obra' },
      { method: 'POST', path: '/webhook/pathology-detect',             desc: 'Vision LLM detecta patologias' },
      { method: 'POST', path: '/webhook/aftercare-submit',             desc: 'Aftercare interno (con auth)' },
      { method: 'POST', path: '/webhook/qc-generate',                  desc: 'Genera checklist QC' },
      { method: 'POST', path: '/webhook/qc-complete',                  desc: 'Actualiza un item del QC', body: '{"qc_id":"...","item_id":"...","status":"pass|fail|skip","comment":"..."}' },
      { method: 'GET',  path: '/webhook/qc-form?qc_id=<uuid>',          desc: 'Form HTML responsive movil para visita a obra' },
      { method: 'POST', path: '/webhook/trigger-energy-assessor',      desc: 'Pre-evaluar HE0/HE1 + CO2', body: '{"project_id":"..."}' },
      { method: 'POST', path: '/webhook/trigger-home-automation',      desc: 'Propuesta domotica', body: '{"project_id":"...","level":"medio","ecosystem_pref":"home_assistant"}' },
      { method: 'POST', path: '/webhook/export-bc3',                    desc: 'Export presupuesto a BC3 (CYPE/Presto)', body: '{"project_id":"..."}' },
      { method: 'POST', path: '/webhook/collab-register',              desc: 'Alta colaborador externo' },
      { method: 'POST', path: '/webhook/collab-assign',                desc: 'Asignar entregable a colaborador' },
      { method: 'POST', path: '/webhook/collab-update',                desc: 'Actualizar status assignment' },
      { method: 'POST', path: '/webhook/admin-note',                   desc: 'Crear nota rapida en proyecto' },
      { method: 'POST', path: '/webhook/admin-note-toggle',            desc: 'Pin/unpin/delete nota' }
    ]
  },
  {
    title: 'Endpoints publicos (cliente / gremio)',
    color: '#f59e0b',
    items: [
      { method: 'POST', path: '/webhook/client-ask',                   desc: 'LLM concierge cliente (token en body)', body: '{"token":"<client_access_token>","question":"..."}' },
      { method: 'POST', path: '/webhook/gdpr-request',                 desc: 'Solicitud RGPD (token en body)' },
      { method: 'POST', path: '/webhook/aftercare-public-submit',     desc: 'Reporte postventa (token + foto)' },
      { method: 'GET',  path: '/webhook/aftercare-public-form?token=<t>', desc: 'Form HTML reporte postventa' },
      { method: 'GET',  path: '/webhook/client-ask-form',              desc: 'Form HTML para client_ask' },
      { method: 'GET',  path: '/webhook/project-summary?token=<t>',    desc: 'Vista publica del proyecto al cliente' },
      { method: 'POST', path: '/webhook/trade-quote-reply',            desc: 'Gremio responde con presupuesto' }
    ]
  },
  {
    title: 'Crons (no callable, ejecucion automatica)',
    color: '#6b7280',
    items: [
      { method: 'CRON', path: 'cron_health_check (06:00 diario)',                desc: 'Verifica funciones SQL + tablas + roundtrip pii' },
      { method: 'CRON', path: 'cron_anomaly_detect (06:00 diario)',              desc: '8 heuristicas SQL anomalias economicas' },
      { method: 'CRON', path: 'cron_data_integrity (05:30 diario)',              desc: '15 chequeos orphans/FKs/fases' },
      { method: 'CRON', path: 'cron_workflow_audit (07:30 diario)',              desc: 'Verifica que crons criticos hayan corrido' },
      { method: 'CRON', path: 'cron_compliance_audit_weekly (Dom 08:00)',        desc: 'Audit semanal de todos los proyectos activos' },
      { method: 'CRON', path: 'cron_aftercare_review (09:30 diario)',            desc: 'Findings nuevos sin asignar' },
      { method: 'CRON', path: 'cron_unknown_agent_alert (09:30 diario)',         desc: 'Alerta si agent_name=unknown_agent en 24h' },
      { method: 'CRON', path: 'cron_aftercare_sla_breach (08:30 diario)',        desc: 'SLA por severidad incidentes asignados' },
      { method: 'CRON', path: 'cron_qc_review (09:15 diario)',                   desc: 'Checklists blocked o sin progreso >7d' },
      { method: 'CRON', path: 'cron_collab_review (10:00 diario)',               desc: 'Colaboradores deadline/delivered/invited' },
      { method: 'CRON', path: 'cron_proposal_to_contract (10:30 diario)',        desc: 'Proposals aprobadas sin contract' },
      { method: 'CRON', path: 'cron_qc_handover_to_acta (11:00 diario)',         desc: 'QC recepcion provisional -> acta' },
      { method: 'CRON', path: 'cron_proposal_response_followup (11:00 diario)',  desc: 'Propuestas sin respuesta cliente >7d' },
      { method: 'CRON', path: 'cron_pathology_review (12:00 diario)',            desc: 'Findings stale >30d + criticos unresolved' },
      { method: 'CRON', path: 'cron_contract_followup (09:45 diario)',          desc: 'Contracts esperando firma >7d' },
      { method: 'CRON', path: 'cron_invoice_approval_followup (11:30 diario)',   desc: 'Facturas pending/sin pagar/disputed' },
      { method: 'CRON', path: 'cron_external_backup (Dom)',                      desc: 'Backup semanal a Drive cifrado' },
      { method: 'CRON', path: 'cron_drive_cleanup (mensual)',                    desc: 'Limpia backups antiguos del Drive' },
      { method: 'CRON', path: 'cron_briefing_postprocess (horario)',             desc: 'Auto-dispatch home_automation si menciona smart' }
    ]
  }
];

function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function methodColor(m) { return { GET:'#3b82f6', POST:'#10b981', CRON:'#6b7280' }[m] || '#666'; }

const sections = groups.map(g => {
  const rows = g.items.map(i => {
    const fullUrl = i.method === 'CRON' ? '' : BASE + i.path;
    const curl = i.method === 'GET' ? `curl -H 'x-api-key: KEY' '${fullUrl}'` :
                 i.method === 'POST' ? `curl -X POST -H 'x-api-key: KEY' -H 'Content-Type: application/json' -d '${esc(i.body || '{}')}' '${fullUrl}'` :
                 '';
    return `<tr>
      <td><span style="background:${methodColor(i.method)};color:white;padding:2px 8px;border-radius:8px;font-size:11px;font-weight:600">${i.method}</span></td>
      <td><code style="font-size:13px">${esc(i.path)}</code></td>
      <td style="font-size:13px;color:#555">${esc(i.desc)}</td>
      ${curl ? `<td><button onclick="navigator.clipboard.writeText(${JSON.stringify(curl)});this.textContent='copiado'" style="font-size:11px;padding:4px 8px;cursor:pointer;border:1px solid #ddd;background:#fff;border-radius:4px">copiar curl</button></td>` : '<td></td>'}
    </tr>`;
  }).join('');
  return `<h2 style="color:${g.color};margin-top:32px">${esc(g.title)}</h2>
<table style="width:100%;border-collapse:collapse;background:#fff;border:1px solid #ddd;border-radius:8px;overflow:hidden">
  <thead><tr style="background:#f0f0f3"><th style="padding:8px;text-align:left;font-size:11px;text-transform:uppercase">method</th><th style="padding:8px;text-align:left;font-size:11px;text-transform:uppercase">path</th><th style="padding:8px;text-align:left;font-size:11px;text-transform:uppercase">descripcion</th><th></th></tr></thead>
  <tbody>${rows}</tbody>
</table>`;
}).join('');

const html = `<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><title>Endpoints — ArquitAI</title>
<style>
  body{font-family:system-ui,sans-serif;max-width:1200px;margin:32px auto;padding:0 20px;color:#222;background:#f7f7f8}
  h1{margin:0 0 8px}
  .sub{color:#888;font-size:13px;margin-bottom:24px}
  table tr td{padding:6px 10px;border-bottom:1px solid #eee;vertical-align:middle}
  table tr:last-child td{border-bottom:none}
  code{background:#eef2ff;padding:2px 6px;border-radius:4px;font-family:monospace}
  .meta{font-size:12px;color:#888;margin-top:24px}
</style></head><body>
<h1>Endpoints — ArquitAI</h1>
<p class="sub">Todos los endpoints disponibles. Sustituye <code>KEY</code> por tu valor de <code>x-api-key</code> antes de pegar el curl.</p>
${sections}
<div class="meta">Generado ${new Date().toISOString()} · Para auditar runtime: <code>POST /webhook/audit-project</code></div>
</body></html>`;

return [{ json: { html } }];
